// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';

/**
* Scale range interpolation method.
*/
type InterpolationMethod = 'rgb' | 'hsl' | 'hsl-long' | 'lab' | 'hcl' | 'hcl-long' | 'cubehelix' | 'cubehelix-long';

/**
* Scale type.
*/
type ScaleType = 'linear' | 'log' | 'pow' | 'sqrt' | 'symlog' | 'time' | 'utc' | 'ordinal' | 'band' | 'point' | 'quantile' | 'quantize' | 'threshold' | 'bin-ordinal';

/**
* Interface describing constructor options.
*/
interface Options {
	/**
	* Domain of associated data values.
	*/
	domain?: Collection | object;

	/**
	* Maximum value in the scale domain (overrides the `domain` option).
	*/
	domainMax?: number;

	/**
	* Minimum value in the scale domain (overrides the `domain` option).
	*/
	domainMin?: number;

	/**
	* Single mid-point value inserted into a two-element domain.
	*/
	domainMid?: number;

	/**
	* Array of raw domain values which overrides the `domain` property.
	*/
	domainRaw?: Collection;

	/**
	* Scale range interpolation method.
	*/
	interpolate?: InterpolationMethod | object;

	/**
	* Scale name.
	*/
	name: string;

	/**
	* Scale range.
	*/
	range?: Collection | object | string;

	/**
	* Boolean indicating whether to reverse the order of the scale range. Default: false.
	*/
	reverse?: boolean;

	/**
	* Boolean indicating whether to round numeric output values to integers. Default: false.
	*/
	round?: boolean;

	/**
	* Scale type. Default: 'linear'.
	*/
	type?: ScaleType;
}

/**
* Interface describing a JSON-serialized scale instance.
*/
interface JSON {
	/**
	* Scale domain.
	*/
	domain?: Collection | object;

	/**
	* Explicit scale domain maximum value.
	*/
	domainMax?: number;

	/**
	* Explicit scale domain minimum value.
	*/
	domainMin?: number;

	/**
	* Mid-point inserted into a two-element scale domain.
	*/
	domainMid?: number;

	/**
	* Raw scale domain values.
	*/
	domainRaw?: Collection;

	/**
	* Scale range interpolation method.
	*/
	interpolate?: InterpolationMethod | object;

	/**
	* Scale name.
	*/
	name: string;

	/**
	* Scale range.
	*/
	range?: Collection | object | string;

	/**
	* Boolean indicating whether to reverse the order of the scale range.
	*/
	reverse: boolean;

	/**
	* Boolean indicating whether to round numeric output value to integers.
	*/
	round: boolean;

	/**
	* Scale type.
	*/
	type: ScaleType;
}

/**
* Interface describing a scale instance.
*/
interface Scale {
	/**
	* Scale domain.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.domain = [ 0, 100 ];
	*
	* var v = scale.domain;
	* // returns [ 0, 100 ]
	*/
	domain?: Collection | object;

	/**
	* Explicit scale domain maximum value.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.domainMax = 100;
	*
	* var v = scale.domainMax;
	* // returns 100
	*/
	domainMax?: number;

	/**
	* Explicit scale domain minimum value.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.domainMin = 0;
	*
	* var v = scale.domainMin;
	* // returns 0
	*/
	domainMin?: number;

	/**
	* Mid-point inserted into a two-element scale domain.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.domainMid = 50;
	*
	* var v = scale.domainMid;
	* // returns 50
	*/
	domainMid?: number;

	/**
	* Raw scale domain values.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.domainRaw = [ 0, 1, 2, 3, 4, 5 ];
	*
	* var v = scale.domainRaw;
	* // returns [ 0, 1, 2, 3, 4, 5 ]
	*/
	domainRaw?: Collection;

	/**
	* Scale range interpolation method.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.interpolate = 'rgb';
	*
	* var v = scale.interpolate;
	* // returns 'rgb'
	*/
	interpolate?: InterpolationMethod | object;

	/**
	* Scale name.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.name = 'yScale';
	*
	* var v = scale.name;
	* // returns 'yScale'
	*/
	name: string;

	/**
	* Scale range.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.range = [ 0, 100 ];
	*
	* var v = scale.range;
	* // returns [ 0, 100 ]
	*/
	range?: Collection | object | string;

	/**
	* Boolean indicating whether to reverse the order of the scale range.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.reverse = true;
	*
	* var v = scale.reverse;
	* // returns true
	*/
	reverse: boolean;

	/**
	* Boolean indicating whether to round numeric output value to integers.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.round = true;
	*
	* var v = scale.round;
	* // returns true
	*/
	round: boolean;

	/**
	* Scale type.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* scale.type = 'log';
	*
	* var v = scale.type;
	* // returns 'log'
	*/
	type: ScaleType;

	/**
	* List of enumerable properties.
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* var v = scale.properties;
	* // returns [ 'domain', 'domainMax', 'domainMin', 'domainMid', 'domainRaw', 'interpolate', 'name', 'range', 'reverse', 'round', 'type' ]
	*/
	readonly properties: Array<string>;

	/**
	* Serializes a scale instance to a JSON object.
	*
	* ## Notes
	*
	* -   This method is implicitly invoked by `JSON.stringify`.
	*
	* @returns JSON object
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* var v = scale.toJSON();
	* // returns { 'name': 'xScale', 'reverse': false, 'round': false, 'type': 'linear' }
	*/
	toJSON(): JSON;
}

/**
* Interface defining a scale constructor which is both "newable" and "callable".
*/
interface Constructor {
	/**
	* Scale constructor.
	*
	* @param options - constructor options
	* @param options.domain - domain of associated data values
	* @param options.domainMax - maximum value in the scale domain (overrides the `domain` option)
	* @param options.domainMin - minimum value in the scale domain (overrides the `domain` option)
	* @param options.domainMid - single mid-point value inserted into a two-element domain
	* @param options.domainRaw - array of raw domain values which overrides the `domain` property
	* @param options.interpolate - scale range interpolation method
	* @param options.name - scale name
	* @param options.range - scale range
	* @param options.reverse - boolean indicating whether to reverse the order of the scale range (default: false)
	* @param options.round - boolean indicating whether to round numeric output values to integers (default: false)
	* @param options.type - scale type (default: 'linear')
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns scale instance
	*
	* @example
	* var scale = new Scale({
	*     'name': 'xScale'
	* });
	*
	* var v = scale.name;
	* // returns 'xScale'
	*/
	new ( options: Options ): Scale;

	/**
	* Scale constructor.
	*
	* @param options - constructor options
	* @param options.domain - domain of associated data values
	* @param options.domainMax - maximum value in the scale domain (overrides the `domain` option)
	* @param options.domainMin - minimum value in the scale domain (overrides the `domain` option)
	* @param options.domainMid - single mid-point value inserted into a two-element domain
	* @param options.domainRaw - array of raw domain values which overrides the `domain` property
	* @param options.interpolate - scale range interpolation method
	* @param options.name - scale name
	* @param options.range - scale range
	* @param options.reverse - boolean indicating whether to reverse the order of the scale range (default: false)
	* @param options.round - boolean indicating whether to round numeric output values to integers (default: false)
	* @param options.type - scale type (default: 'linear')
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns scale instance
	*
	* @example
	* var scale = Scale({
	*     'name': 'xScale'
	* });
	*
	* var v = scale.name;
	* // returns 'xScale'
	*/
	( options: Options ): Scale;
}

/**
* Scale constructor.
*
* @param options - constructor options
* @param options.domain - domain of associated data values
* @param options.domainMax - maximum value in the scale domain (overrides the `domain` option)
* @param options.domainMin - minimum value in the scale domain (overrides the `domain` option)
* @param options.domainMid - single mid-point value inserted into a two-element domain
* @param options.domainRaw - array of raw domain values which overrides the `domain` property
* @param options.interpolate - scale range interpolation method
* @param options.name - scale name
* @param options.range - scale range
* @param options.reverse - boolean indicating whether to reverse the order of the scale range (default: false)
* @param options.round - boolean indicating whether to round numeric output values to integers (default: false)
* @param options.type - scale type (default: 'linear')
* @throws options argument must be an object
* @throws must provide valid options
* @returns scale instance
*
* @example
* var scale = new Scale({
*     'name': 'xScale'
* });
* // returns <Scale>
*
* var v = scale.toJSON();
* // returns { 'name': 'xScale', 'reverse': false, 'round': false, 'type': 'linear' }
*/
declare var ctor: Constructor;


// EXPORTS //

export = ctor;

// eslint-doctest-alias: Scale
